import{_ as a,o as s,c as t,ag as n}from"./chunks/framework.BwSLX4ak.js";const u=JSON.parse('{"title":"Inventory queries and textures","description":"","frontmatter":{},"headers":[],"relativePath":"en/shitbot/inventory.md","filePath":"en/shitbot/inventory.md"}'),i={name:"en/shitbot/inventory.md"};function o(r,e,l,d,c,p){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="inventory-queries-and-textures" tabindex="-1">Inventory queries and textures <a class="header-anchor" href="#inventory-queries-and-textures" aria-label="Permalink to &quot;Inventory queries and textures&quot;">​</a></h1><h2 id="enable-inventory-queries" tabindex="-1">Enable inventory queries <a class="header-anchor" href="#enable-inventory-queries" aria-label="Permalink to &quot;Enable inventory queries&quot;">​</a></h2><p>Check these settings in <code>config.yml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">onebot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  commands</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    inventory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">inventory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  template</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;default&quot;</span></span></code></pre></div><p>Save and run <code>/shitbot reload</code>. Spigot and Nukkit-MOT save online inventories periodically and again when players leave.</p><p>Edit aliases and replies under <code>commands.inventory</code> and <code>messages</code> in the selected <code>lang/*.yml</code>. Edit image appearance under <code>inventory</code> in <code>templates/*.yml</code>; copy the default theme and select it with <code>inventory.template</code>. See <a href="/docs/en/shitbot/configuration.html#lightweight-theme-files">Configuration</a>.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><p>With <code>language: &quot;en_US&quot;</code>, group members send <code>inventory</code> or <code>my inventory</code> to select a character bound to their QQ automatically. Aliases can be changed in the language file.</p><p>For multiple Minecraft IDs, use <code>inventory &lt;Minecraft ID&gt;</code> or <code>my inventory &lt;Minecraft ID&gt;</code>. The exact ID must belong to the sender&#39;s QQ before the snapshot is read and rendered. Other users&#39; characters cannot be queried. The corresponding Chinese aliases are <code>背包</code> and <code>我的背包</code>.</p><h2 id="external-inventory-template" tabindex="-1">External inventory template <a class="header-anchor" href="#external-inventory-template" aria-label="Permalink to &quot;External inventory template&quot;">​</a></h2><p>Enabling advanced templates creates <code>image-templates/inventory/</code>. Use <code>/shitbot editor</code> to edit equipment, storage, hotbar, counts, and durability layers. Set the preview context&#39;s <code>player</code> to an actual player name, then save and publish changes.</p><p>Set <code>image-templates.commands.inventory.enabled</code> to <code>true</code> in <code>commands.yml</code> and reload to query a bound character with <code>custom inventory</code>. This entry uses the same snapshots, binding checks, and texture settings, and requires <code>inventory.enabled: true</code>. The original <code>inventory</code> command retains its native image. See <a href="/docs/en/shitbot/image-templates.html#profile-and-inventory-templates">Profile and inventory templates</a> for activation and data fields.</p><h2 id="offline-queries" tabindex="-1">Offline queries <a class="header-anchor" href="#offline-queries" aria-label="Permalink to &quot;Offline queries&quot;">​</a></h2><p>Online snapshots are saved every 60 seconds by default and immediately on logout. They are retained for 30 days by default, so QQ users can query the latest inventory while offline.</p><p>If the player has never joined a server that saves snapshots, the snapshot expired, or <code>inventory.enabled</code> is off, the bot reports that no snapshot is available. New fields missing from older snapshot formats require the player to join again.</p><h2 id="server-networks" tabindex="-1">Server networks <a class="header-anchor" href="#server-networks" aria-label="Permalink to &quot;Server networks&quot;">​</a></h2><p>Proxies do not have live inventories. Connect the proxy and all Spigot backends to the same MySQL database:</p><ul><li>Backends can disable <code>onebot.enabled</code> while keeping <code>inventory.enabled</code> to save periodic and logout snapshots.</li><li>BungeeCord/Velocity receives QQ commands, reads shared snapshots, and renders images.</li><li>SQLite is for a single server and cannot serve as a shared multiprocess database.</li></ul><p>The rendering proxy also needs the same item resources. Put client JARs, packs, and mod JARs where the proxy can read them and use absolute paths in <code>resource-archives</code>, or copy precisely exported <code>item-icons</code>.</p><h2 id="texture-resolution-across-versions" tabindex="-1">Texture resolution across versions <a class="header-anchor" href="#texture-resolution-across-versions" aria-label="Permalink to &quot;Texture resolution across versions&quot;">​</a></h2><p>Resolution order:</p><ol><li><code>item-icons/&lt;namespace&gt;/&lt;path&gt;__cmd_&lt;custom-model-data&gt;.png</code>.</li><li><code>item-icons/&lt;namespace&gt;/&lt;path&gt;__data_&lt;legacy-data-value&gt;.png</code>.</li><li><code>item-icons/&lt;namespace&gt;/&lt;path&gt;.png</code>.</li><li>Directories, resource packs, client JARs, or resource JARs explicitly listed in <code>inventory.icons.resource-archives</code>.</li><li>Automatically discovered <code>resources</code>, <code>resourcepacks</code>, <code>server-resource-packs</code>, <code>mods</code>, <code>versions</code>, and client JARs.</li></ol><p>ShitBot&#39;s Spigot compatibility starts at 1.8.8. Its texture resolver covers resource formats used from 1.8.8 through the documented 26.x line, including direct texture directories from older packs:</p><ul><li>Legacy <code>textures/items</code> and <code>textures/blocks</code>.</li><li>JSON item/block models from 1.8 onward, including <code>builtin/generated</code> and <code>builtin/handheld</code>.</li><li>Bukkit material names, legacy registry names, and data variants from 1.8–1.12.</li><li>Namespaced item IDs after the 1.13 flattening.</li><li><code>custom_model_data</code>, <code>damage</code>, and <code>damaged</code> in traditional model <code>overrides</code>.</li><li>1.21.4–26.x <code>assets/&lt;namespace&gt;/items/*.json</code>: model, composite, condition, range_dispatch, select, and basic special models.</li><li>Bounded snapshots of modern CustomModelData floats, flags, strings, and colors.</li><li>Player head textures through GameProfile, PlayerProfile, and ResolvableProfile from 1.8 onward.</li></ul><p>Ordinary 2D items combine all <code>layer0...layer15</code>. Ordinary block models generate isometric icons from inherited top/side/face textures. Animated PNGs use their first frame, so the animation strip is not compressed into one slot.</p><h3 id="where-to-put-the-client-jar" tabindex="-1">Where to put the client JAR <a class="header-anchor" href="#where-to-put-the-client-jar" aria-label="Permalink to &quot;Where to put the client JAR&quot;">​</a></h3><p>ShitBot does not include Mojang&#39;s vanilla textures. The instance rendering images must read the matching client JAR or a complete vanilla resource pack.</p><p>Default standalone layout:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server/</span></span>
<span class="line"><span>├─ mods/</span></span>
<span class="line"><span>│  └─ 1.8.9-client.jar</span></span>
<span class="line"><span>└─ plugins/ShitBot/</span></span></code></pre></div><p>The default <code>mods-directory: ../../mods</code> resolves from <code>plugins/ShitBot</code> to <code>server/mods</code>. The file must be a client JAR containing <code>assets/minecraft</code>. Forge/OptiFine installers, launcher components, or trimmed archives containing only classes cannot substitute for client resources.</p><p>For explicit priority:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">inventory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  icons</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    resource-archives</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;D:/Minecraft/versions/1.8.9/1.8.9.jar&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;D:/Minecraft/resourcepacks/server-pack.zip&quot;</span></span></code></pre></div><p>The resource index builds asynchronously at startup. The first query waits at most <code>index-wait-ms</code>. File timestamps and sizes are checked every <code>refresh-seconds</code>; negative caching does not permanently hide textures after adding or replacing a JAR.</p><h3 id="player-heads" tabindex="-1">Player heads <a class="header-anchor" href="#player-heads" aria-label="Permalink to &quot;Player heads&quot;">​</a></h3><p>Spigot backends read <code>textures</code> from legacy CraftMetaSkull/GameProfile and modern PlayerProfile/ResolvableProfile. Only the hexadecimal content hash for <code>textures.minecraft.net</code> is saved. The renderer downloads skins from that fixed Mojang domain, combines the base head and hat layer, and caches them under:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/ShitBot/inventory-head-cache/</span></span></code></pre></div><p>Cache cleanup runs asynchronously at startup, retaining at most 4,096 files or 64 MiB. If the server cannot reach <code>textures.minecraft.net</code>, it temporarily uses the resource pack&#39;s generic player head and retries after 30 seconds without blocking Bukkit&#39;s main thread.</p><p>Old format 1 and 2 offline snapshots have no head texture hash. After upgrading, have the character join and wait for a periodic snapshot, or query while online. A new format 3 snapshot is required for custom heads.</p><h2 id="mod-and-custom-renderer-limits" tabindex="-1">Mod and custom renderer limits <a class="header-anchor" href="#mod-and-custom-renderer-limits" aria-label="Permalink to &quot;Mod and custom renderer limits&quot;">​</a></h2><p>Forge, NeoForge, and common hybrid servers attempt to reflect the actual <code>modid:item_name</code> from NMS/loader registries and read the mod JAR&#39;s <code>assets</code>. Ordinary JSON models can display automatically.</p><p>A generic server resolver cannot fully reproduce appearances generated by arbitrary client code or live context from resource files alone:</p><ul><li>Custom TESR/BEWLR, ISTER, or Fabric BuiltinItemRenderer implementations.</li><li>Models changing with full NBT, capabilities, fluids, energy, or client state.</li><li>Maps, banners, shield patterns, and other models needing world or complete pattern context.</li><li>Custom OBJ/GLTF loaders and shader effects.</li></ul><p>Override these with PNGs exported from actual client rendering:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/ShitBot/item-icons/</span></span>
<span class="line"><span>├─ minecraft/diamond.png</span></span>
<span class="line"><span>├─ create/precision_mechanism.png</span></span>
<span class="line"><span>├─ example/custom_item__cmd_10001.png</span></span>
<span class="line"><span>└─ minecraft/wool__data_14.png</span></span></code></pre></div><p>Only items without an available icon show the question-mark placeholder. Slots, counts, and durability remain visible.</p><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h2><ul><li>The default 60-second standalone snapshot interval usually needs no reduction.</li><li>Large networks can use 4–8 MySQL <code>database.async-threads</code> and set <code>database.maximum-queued-tasks</code> to an acceptable backlog.</li><li>Keep <code>render.maximum-concurrent</code> around 2–4; <code>render.maximum-queued</code> limits pending queries.</li><li>Resource indexing has a separate thread, avoiding deadlocks with PNG rendering workers.</li><li>Icon caches include a resource index generation; resource updates invalidate old results.</li><li>Missing icons are negatively cached for only 30 seconds.</li><li>Icon, snapshot, and rendering caches are bounded.</li><li>Inventory fields are copied only on a safe thread: Bukkit&#39;s main thread or the player&#39;s region thread on Folia. Compression, SQL, resource scanning, and rendering run asynchronously.</li></ul>`,47)])])}const m=a(i,[["render",o]]);export{u as __pageData,m as default};
